import * as React from 'react';
import { Spinner } from '@/components/slipstream/spinner';
import { cn } from '@/lib/utils';

/** A single file attached to a message or prompt. Display-only; upload logic stays consumer-side. */
export interface AttachmentItem {
  id: string;
  /** File name, including extension. */
  name: string;
  /** Human-readable size, e.g. "2.4 MB". */
  size?: string;
  /** MIME type or simple kind used for the chip label. */
  type?: string;
  /** Optional image thumbnail URL. */
  previewUrl?: string;
  status?: 'uploading' | 'done' | 'error';
}

export interface AttachmentProps {
  attachment: AttachmentItem;
  /** Called when the user removes the attachment; omit to hide the remove control. */
  onRemove?: (attachment: AttachmentItem) => void;
  className?: string;
}

const Attachment = React.forwardRef<HTMLDivElement, AttachmentProps>(
  ({ attachment, onRemove, className, ...props }, ref) => {
    return (
      <div
        ref={ref}
        className={cn(
          'inline-flex items-center gap-2 rounded-md border border-border bg-muted/50 px-2 py-1.5 text-sm max-w-xs',
          className
        )}
        {...props}
      >
        {attachment.previewUrl ? (
          <img
            src={attachment.previewUrl}
            alt=""
            aria-hidden="true"
            className="h-8 w-8 rounded object-cover flex-shrink-0"
          />
        ) : (
          <span
            aria-hidden="true"
            className="flex h-8 w-8 items-center justify-center rounded bg-secondary text-[10px] font-semibold uppercase text-secondary-foreground flex-shrink-0"
          >
            {(attachment.type ?? attachment.name.split('.').pop() ?? '?').slice(0, 4)}
          </span>
        )}

        <div className="min-w-0 flex-1">
          <div className="truncate font-medium text-foreground" title={attachment.name}>
            {attachment.name}
          </div>
          <div className="text-xs text-muted-foreground">
            {attachment.status === 'uploading'
              ? 'Uploading...'
              : [attachment.size, attachment.type].filter(Boolean).join(' · ') || null}
          </div>
        </div>

        {attachment.status === 'uploading' && (
          <Spinner size="sm" label="Uploading" aria-label="Uploading" className="flex-shrink-0" />
        )}

        {onRemove && (
          <button
            type="button"
            onClick={() => onRemove(attachment)}
            aria-label={`Remove ${attachment.name}`}
            className="flex-shrink-0 rounded p-0.5 text-muted-foreground hover:text-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
          >
            ✕
          </button>
        )}
      </div>
    );
  }
);
Attachment.displayName = 'Attachment';

export { Attachment };

import * as React from 'react';
import { cn } from '@/lib/utils';
import { Attachment } from './Attachment';
import type { AttachmentItem } from './Attachment';

export interface AttachmentListProps {
  attachments: AttachmentItem[];
  /** Passed through to every Attachment; omit to hide remove controls. */
  onRemove?: (attachment: AttachmentItem) => void;
  className?: string;
}

const AttachmentList = React.forwardRef<HTMLDivElement, AttachmentListProps>(
  ({ attachments, onRemove, className, ...props }, ref) => {
    if (attachments.length === 0) {
      return null;
    }

    return (
      <div ref={ref} className={cn('flex flex-wrap gap-2', className)} {...props}>
        {attachments.map((attachment) => (
          <Attachment key={attachment.id} attachment={attachment} onRemove={onRemove} />
        ))}
      </div>
    );
  }
);
AttachmentList.displayName = 'AttachmentList';

export { AttachmentList };

export { Attachment } from './Attachment';
export type { AttachmentProps } from './Attachment';
export type { AttachmentItem } from './Attachment';
export { AttachmentList } from './AttachmentList';
export type { AttachmentListProps } from './AttachmentList';

{
  "id": "attachment",
  "name": "Attachment / AttachmentList",
  "tier": "molecule",
  "description": "File chips for prompts and messages. `Attachment` renders one file; `AttachmentList` renders a wrapping row. Display-only: upload and file-system logic stay in the consumer.",
  "designIntent": "Show what files are part of a conversation turn (name, size, type, thumbnail, upload status) without coupling the library to any upload implementation.",
  "props": [
    { "name": "attachment", "type": "AttachmentItem", "required": true, "description": "File descriptor: id, name, size, type, previewUrl, status." },
    { "name": "attachments", "type": "AttachmentItem[]", "required": true, "description": "Files to display (AttachmentList)." },
    { "name": "onRemove", "type": "(attachment) => void", "required": false, "description": "Remove callback; omit to hide remove controls." }
  ],
  "examples": [
    {
      "title": "Prompt attachments",
      "code": "<AttachmentList attachments={[{ id: '1', name: 'spec.pdf', size: '2.4 MB', status: 'done' }]} onRemove={remove} />"
    },
    {
      "title": "Uploading image",
      "code": "<Attachment attachment={{ id: '2', name: 'chart.png', previewUrl: '/chart.png', status: 'uploading' }} />"
    }
  ],
  "antiPatterns": [
    { "title": "Do not use Attachment for drag-and-drop targets", "explanation": "The chip displays an existing item; build dropzones in the consumer and render AttachmentList once items exist." }
  ],
  "accessibility": [
    { "feature": "Remove control", "implementation": "Icon-only remove button has an aria-label including the file name." },
    { "feature": "Upload status", "implementation": "Uploading state is announced via role=status." },
    { "feature": "Decorative thumbnails", "implementation": "Preview images are aria-hidden; the file name carries the meaning." }
  ],
  "package": "@slipstream-ui/ai",
  "importPath": "@slipstream-ui/ai",
  "version": "0.0.1"
}
